\normalfont\label{re2}
By using Lagrange duality, it can easily be verified that the optimal solution of the optimization problem that consists in maximizing the \textit{weighted Shannon entropy} (see, for instance, \cite{GUI}) subject to linear constraints
\begin{eqnarray*}
~~\max_{x_j\geq 0,~j=1,\hdots,m,\atop \sum\limits_{j=1}^m p_jx_j=1} \left\{-\sum_{j=1}^mp_jx_j\ln x_j\right\},
\end{eqnarray*}
is $\bar x_i=1/(\sum_{j=1}^mp_j),~i=1,\hdots,m$, and its optimal objective value is equal to $\ln (\sum_{j=1}^mp_j)$.
Hence, if $H>\ln (\sum_{j=1}^mp_j)$, then the feasible set of $(P)$ is empty. Moreover, if $H=\ln (\sum_{j=1}^mp_j)$, then the $x$-components of any optimal solution $(\bar x, \bar y)$ to $(P)$ are $\bar x_j=1/(\sum_{j=1}^mp_j)$, $j=1,\hdots,m$, and $(P)$ reduces to the unconstrained convex optimization problem
\begin{eqnarray}\label{pr2}
~~c_p^{\top} \bar x+\inf_{y\in \mathbb{R}^d,~By\leqq h-A_p\overline{x}} \sigma_D(y),
\end{eqnarray}
iteratively solvable by existing proximal splitting algorithms.    







Finally, to determine the minimal value of $-\sum_{j=1}^mp_jx_j\ln x_j$ subject to $\sum_{j=1}^mp_jx_j=1$, $x_j\geq 0$, $j=1,\hdots, m$, we set $z_j=p_jx_j,~j=1,\hdots,m$, and get the following minimization problem consisting in minimizing the \textit{Kullback-Leibler entropy} subject to the usual linear constraints
\begin{equation}\label{eq3}
~~\inf_{z_j\geq 0,~j=1,\hdots,m,\atop \sum\limits_{j=1}^mz_j=1}\left\{-\sum\limits_{j=1}^mz_j\ln\left(\frac{z_j}{p_j}\right)\right\}=\min_{z_j\geq 0,~j=1,\hdots,m,\atop \sum\limits_{j=1}^mz_j=1}\left\{-\sum\limits_{j=1}^m(z_j\ln z_j-z_j\ln p_j)\right\}.
\end{equation}
For attaining the minimum in \eqref{eq3}, the sum $-\sum_{j=1}^mz_j\ln z_j\geq 0$ must be equal to zero and, as $z_j\ln p_j\leq 0$ for all $j=1,\hdots,m$, an optimal solution to \eqref{eq3} is $\bar z_l=1$, $\bar z_j=0$ for all $j=1,\hdots,m,~j\neq l$, where $l = \min\{i\in \{1,\hdots,m\}: p_i=\min\{p_1,\hdots,p_m\}\}$. Hence, we have that $\bar x_l=1/p_l$, $\bar x_j=0$ for all $j=1,\hdots,m$, $j\neq l$, solves $(P)$, whose minimal value is $\min\{\ln p_1,\hdots,\ln p_m\}=\ln p_l$. In this case, the constraint involving entropy of $(P)$ is automatically fulfilled, and $(P)$ collapses into a convex optimization problem with affine constraints similar to \eqref{pr2}, which can be solved via existing splitting proximal point methods.

\normalfont\label{re3}
Note that the objective function of the problem $(P)$ is proper, convex and lower semicontinuous. For any fixed $y\in \mathbb{R}^n$, the set                                                                                                           
$$
\mathcal{A}=\left\{x\in \mathbb{R}_+^m:A_px+By\leqq h,~\sum\limits_{j=1}^mp_jx_j=1,~ \sum\limits_{j=1}^mp_jx_j\ln x_j\leq -H\right\}
$$
is closed, convex and bounded, thus also compact, so one gets by the generalized Weierstrass theorem that the infimum regarding $x\in \mathcal{A}$ is attained in the optimization problem $(P)$ for any $y\in \mathbb{R}^n$.

$(a)$ Recall the observation in \eqref{setD} and that $\sigma_D=\sigma_{\widetilde{D}}+\cdot$ as well as $\overline{\lambda} ^{\top}\widetilde{B}(\overline{y},\overline{t})=\overline{\lambda}^{\top}\overline{y}+\overline{t}$ holds. Then the optimality conditions $(i)$-$(vi)$ of Theorem \ref{theoremChapter1:3.2} are direct consequences of Theorem \ref{theoremChapter1:3}. Further, the second equality of the optimality condition $(iii)$ can be achieved from the first equality of the optimality condition $(iii)$, the feasibility of $(\overline{x},\overline{y},\overline{t})$ and the optimality condition $(v)$, i.e. $\sum_{i=1}^n\overline{\lambda}=1$,
\begin{eqnarray}
&&\sum\limits_{i=1}^n\overline{\lambda}_i\left(\sum\limits_{j=1}^mp_ja_{ij}\overline{x}_j
    -\overline{y}_i\right)=\overline{t}\geq\max\limits_{1\leq i\leq n}\left\{\sum\limits_{j=1}^mp_ja_{ij}\overline{x}_j-\overline{y}_i\right\}\notag\\
&=&\sum_{i=1}^n\overline{\lambda}_i\max\limits_{1\leq i\leq n}\left\{\sum\limits_{j=1}^mp_ja_{ij}\overline{x}_j-\overline{y}_i\right\}\geq\sum\limits_{i=1}^n\overline{\lambda}_i\left(\sum\limits_{j=1}^mp_ja_{ij}\overline{x}_j
    -\overline{y}_i\right).\label{tsum}
\end{eqnarray}
Moreover, it holds by \eqref{tsum} that
\begin{eqnarray}
\sum\limits_{i=1}^n\overline{\lambda}_i\left(\overline{t}-\left(\sum\limits_{j=1}^mp_ja_{ij}\overline{x}_j-\overline{y}_i\right)\right)=0\label{tsum2}
\end{eqnarray}
and since $\lambda_i\geq 0$ as well as  $\overline{t}-\left(\sum_{j=1}^mp_ja_{ij}\overline{x}_j-\overline{y}_i\right)\geq0$ for all $i=1,\hdots,n$, one gets that all the terms in \eqref{tsum2} are nonnegative and must therefore be equal to zero, which proves the optimality condition $(vii)$.

$(b)$ All calculations done in $(a)$ hold also in the reverse direction.

\normalfont Notice that \cite[Remark 3.3.8]{DVO} points up that the optimality condition $(i)$ in Theorem \ref{theoremChapter1:3.2} is equivalent, after some simplifications, to
\begin{equation}\label{equation0}
\left\{
\begin{array}{l}
\sum_{i=1}^n\overline{\lambda}_i=1,~\overline{\lambda}\in \partial\sigma_{\widetilde D}(\overline{y}),\\
\sum_{i=1}^n\overline{\lambda}_ip_ja_{ij}+\overline{\gamma} p_j+\overline{\beta}p_j(\ln \overline{x}_j+1)=0,~j=1,\hdots,m.
\end{array}\right.
\end{equation}
Multiplying the last equality with $\overline{x}_j$ and taking the sum over all $j=1,\hdots,m$, leads to
\begin{eqnarray}
\sum_{j=1}^m\sum_{i=1}^n\overline{\lambda}_ip_ja_{ij}\overline{x}_j+\overline{\gamma}\sum_{j=1}^m p_j\overline{x}_j+\overline{\beta}\sum_{j=1}^m p_j\overline{x}_j(\ln \overline{x}_j+1)=0.\label{equation1}
\end{eqnarray}
From the optimality conditions $(ii)-(iii)$ in Theorem \ref{theoremChapter1:3.2} one gets $$v(P)=\sum\limits_{i=1}^n\sum\limits_{j=1}^m\overline{\lambda}_ip_ja_{ij}\overline{x}_j,$$
while optimality condition $(iv)$ in the same statement yields $-H=\sum_{j=1}^mp_j\overline{x}_j\ln \overline{x}_j$. Using that $\sum_{j=1}^mp_j\overline{x}_j=1$, \eqref{equation1} turns into
\begin{eqnarray}
\overline{\gamma}= -v(P)-\overline{\beta}\left(1-H\right).\label{equation2}
\end{eqnarray}
By combining \eqref{equation0} and \eqref{equation2} one has
\begin{eqnarray*}
&&\sum_{i=1}^n\overline{\lambda}_ip_ja_{ij}-p_j\left(v(P)+\overline{\beta}\left(1-H\right)\right)+\overline{\beta}p_j(\ln \overline{x}_j+1)=0\\
&\Leftrightarrow&\sum_{i=1}^n\overline{\lambda}_ia_{ij}+\overline{\beta}(\ln \overline{x}_j+H)=v(P),~j=1,\hdots,m,
\end{eqnarray*}
therefore the optimal solution $(\overline{\beta},\overline{\lambda})$ to the dual problem $(D_L')$ is the solution of the linear equality system
$$\left\{
\begin{array}{l}
\sum\limits_{i=1}^n\lambda_ia_{ij}+\beta(\ln \overline{x}_j+H)=v(P),~j=1,\hdots,m,\\
\sum\limits_{i=1}^n\lambda_i=1,\\
\lambda\in \widetilde D \cap \mathbb{R}^n_+,\\
  \beta > 0.
\end{array}\right.$$

\normalfont
If one has an optimal solution $(\overline{\beta},\overline{\lambda})$ to the dual problem $(D'_L)$, then an optimal solution $(\overline{x},\overline{y},\overline{t})$ to $(P')$ is also determinable by using the optimality conditions given in Theorem \ref{theoremChapter1:3.2}. The component $\overline{x}$ can then be obtained by solving a linear equality system of the form
\begin{eqnarray}
&&\left\{
\begin{array}{l}\sum\limits_{i=1}^n\overline{\lambda}_ia_{ij}+\overline{\beta}(\ln x_j+H)=v(D'_L),~j=1,\hdots,m,\\
\sum\limits_{j=1}^m\sum\limits_{i=1}^n\overline{\lambda}_ip_ja_{ij}x_j=v(D'_L),
\end{array}\right.\notag\\
&\Leftrightarrow&\left\{
\begin{array}{l}x_j=e^{\frac{1}{\overline{\beta}}\left(v(D'_L)-\sum\limits_{i=1}^n\overline{\lambda}_ia_{ij}\right)-H},~j=1,\hdots,m,\\
\sum\limits_{j=1}^m\sum\limits_{i=1}^n\overline{\lambda}_ip_ja_{ij}x_j=v(D'_L),
\end{array}\right.\label{x_solution}
\end{eqnarray}
while $\overline{y}$ and $\overline{t}$ can be deduced from $\overline{y}\in \partial \delta_{\widetilde{D}}(\overline{\lambda})$ and  $\overline{t}=\sum_{i=1}^n\overline{\lambda}_i\left(\sum_{j=1}^mp_ja_{ij}\overline{x}_j-\overline{y}_i\right)$. Alternatively, one can find $(\overline{y},\overline{t})$ by solving (for instance, with a proximal splitting algorithm) the optimization problem
\begin{eqnarray*}
\inf_{y\in \mathbb{R}^n}\left\{\max_{1\leq i \leq n}\left\{\sum_{j=1}^mp_ja_{ij}\overline{x}_j-y_i\right\}+\sigma_{\widetilde{D}}(y)\right\}.
\end{eqnarray*}

Note that a solution $\overline{x}_j$, $j=1,\hdots,m$, of the linear equality system in \eqref{x_solution} fulfills of course the optimality conditions of $(P')$, too. Let $\overline{x}_j$, $j=1,\hdots,m$, be an solution of the linear equality system in \eqref{x_solution}, then by multiplying in both sides of the equalities in the first line of \eqref{x_solution} with the corresponding $p_j$, $j=1,\hdots,n$, and taking the sum over all $j=1,\hdots,m$, one gets that
\begin{eqnarray*}
&& \sum_{j=1}^m p_j \overline{x}_j=\sum_{j=1}^m p_j e^{\frac{1}{\overline{\beta}_j}\left(v(D'_L)-\sum\limits_{i=1}^n\overline{\lambda}_ia_{ij}\right)-H}=e^{\frac{v(D'_L)}{\overline{\beta}}}\underbrace{\sum_{j=1}^m p_j e^{-\frac{\sum\limits_{i=1}^n\overline{\lambda}_ia_{ij}}{\overline{\beta}}-H}}_{=e^{-\frac{v(D'_L)}{\overline{\beta}}}}=1.
\end{eqnarray*}
Moreover, the first equality in \eqref{x_solution} is equivalent to
\begin{eqnarray*}
\ln \overline{x}_j=\frac{1}{\overline{\beta}}\left(v(D'_L)-\sum_{i=1}^n\overline{\lambda}_ia_{ij}\right)-H\quad \forall j=1,\hdots,m,
\end{eqnarray*}
and by multiplying in both sides with $\overline{x}_jp_j$ and taking the sum over all $j=1,\hdots,m$, it follows that
\begin{eqnarray*}
&&\sum_{j=1}^m\overline{x}_jp_j\ln \overline{x}_j=\frac{1}{\overline{\beta}}\left(\sum_{j=1}^m\overline{x}_jp_jv(D'_L)-\sum_{j=1}^m\sum_{i=1}^n\overline{\lambda}_ip_ja_{ij}\overline{x}_j\right)-\sum_{j=1}^m\overline{x}_jp_jH\\
&=&\frac{1}{\overline{\beta}}\underbrace{\left(v(D'_L)-\sum_{j=1}^m\sum_{i=1}^n\overline{\lambda}_ip_ja_{ij}\overline{x}_j\right)}_{=0}-H=-H,
\end{eqnarray*}
where $v(P')=\sum_{j=1}^m\sum_{i=1}^n\overline{\lambda}_ip_ja_{ij}\overline{x}_j$, i.e. $v(P')=v(D'_L)$.

\normalfont  Let $X^*\in L^q$, where $q\in (1, +\infty)$, $\alpha\in (0,1]$ and the function $g:L^q\rightarrow \overline{\mathbb{R}}$ be defined by
\begin{eqnarray*}
g(X^*)= \left\{ \begin{array}{ll} 0, \qquad
\textnormal{if } X^*\in L^q_+,~ \mathbb{E}(X^*\ln(X^*))\leq -\ln\alpha,~\mathbb{E}X^*=1,\\
+ \infty,  \textnormal{ otherwise}. \end{array} \right.
\end{eqnarray*}

It can be verified that $g$ is proper, convex and lower semicontinuous, and its conjugate function $g^*:L^p\rightarrow \overline{\mathbb{R}}$
(where $p\in (1, +\infty)$ is the \textit{H\"older conjugate} of $q$, i.e. it fulfills $1/p+1/q=1$) is given by
\begin{eqnarray}
g^*(X)=\sup_{X^*\in L^q_+,~\mathbb{E}X^*=1,\atop \mathbb{E}(X^*\ln(X^*))\leq -\ln\alpha} \langle X^*,X\rangle.\label{g_formula}
\end{eqnarray}
For a fixed $X\in L^p$, the negative of the right-hand side in \eqref{g_formula} is a convex optimization problem. By the corresponding weak Lagrange duality, one obtains
\begin{eqnarray}
g^*(X)\leq\inf_{\lambda\geq 0,~\gamma\in \mathbb{R}}\left\{\sup_{X^*\in L^q_+}\{\langle X^*,X\rangle-\lambda\mathbb{E}(X^*\ln(X^*))-\gamma\langle 1_{\Omega},X^*\rangle\}+\gamma-\lambda\ln\alpha\right\}.\label{g_formula1}
\end{eqnarray}
Moreover, applying \cite[Theorem 3.2.9.]{DVO} follows that the strong duality holds for this pair of primal-dual optimization problems, i.e. in \eqref{g_formula1} equality holds and the infimum in the right-hand side is attained. To see this, let $C=\mathbb{R}_+\times \{0\}$ and take $h:L^q\rightarrow \mathbb{R}^2\cup\{\infty_{\mathbb{R}^2_+}\}$,
\begin{eqnarray*}
h(X^*)= \left\{ \begin{array}{ll} (\mathbb{E}(X^*\ln(X^*))+\ln\alpha,\mathbb{E}X^*-1)^{\top},
\textnormal{ if } X^*\in L^q_+,\\
\infty_{\mathbb{R}^2_+},  \textnormal{ otherwise,} \end{array} \right.
\end{eqnarray*}
then it holds $h(\operatorname*{dom} \langle X,\cdot\rangle\cap \operatorname*{dom} h)=h(\operatorname*{dom} h)=[\ln\alpha+\min_{X^*\in L^q_+}\mathbb{E}(X^*\ln(X^*)),+\infty)\times[-1,+\infty)$, where it is obvious that $\min_{X^*\in L^q_+}\mathbb{E}(X^*\ln(X^*))<0$, and therefore,
\begin{eqnarray*}
0_{\mathbb{R}^2}\in\operatorname*{ri}\left(h(\operatorname*{dom} h)+C \right)=\operatorname*{ri} \left[\ln\alpha+\min_{X^*\in L^q_+}\mathbb{E}(X^*\ln(X^*)),+\infty\right)\times\operatorname*{ri}[-1,+\infty).
\end{eqnarray*}
As the refined Slater constraint qualification is fulfilled, there is strong duality for the primal-dual pair of optimization problems mentioned above, hence
\begin{eqnarray*}
g^*(X)=\min_{\lambda\geq 0,~\gamma\in \mathbb{R}}\left\{\sup_{X^*\in L^q_+}\{\langle X^*,X\rangle-\lambda\mathbb{E}(X^*\ln(X^*))-\gamma\langle1_{\Omega},X^*\rangle\}+\gamma-\lambda\ln\alpha\right\}.
\end{eqnarray*}
In order to compute the quantity in the right-hand side of this equality we distinguish two cases. When $\lambda>0$, then we have by the interchangeability of minimization and integration as well as the considerations we made regarding the functions $\varphi$ and $q$ (while deriving the simplified formula of $(D_L)$ that
$$
\min_{\lambda>0,~\gamma\in \mathbb{R}}\left\{\sup_{X^*\in L^q_+}\{\langle X^*,X\rangle-\lambda\mathbb{E}(X^*\ln(X^*))-\gamma\langle1_{\Omega},X^*\rangle\}+\gamma-\lambda\ln\alpha\right\}=\min_{\lambda>0,~\gamma\in \mathbb{R}}\bigg\{\mathbb{E}$$
$$\left(\sup_{x^*\in\mathbb{R}_+}\{ Xx^* -\lambda x^*\ln(x^*)-\gamma x^*\}\right)+\gamma-\lambda\ln\alpha\bigg\}
= \min_{\lambda>0,~\gamma\in \mathbb{R}}\left\{\lambda\mathbb{E}\left(e^{\frac{X+\gamma-\lambda}{\lambda}}\right)+\gamma-\lambda\ln\alpha\right\}
$$
\begin{eqnarray}
=\min_{\lambda>0}\left\{\lambda\ln\left(\mathbb{E}\left(e^{\frac{X-\lambda+\lambda}{\lambda}}\right)\right)-\lambda\ln\alpha\right\}=
\min_{\lambda>0}\left\{\lambda\ln\left(\frac{\mathbb{E}\left(e^{\frac{X}{\lambda}}\right)}{\alpha}\right)\right\}.\label{g_formula12}
\end{eqnarray}


On the other hand, when $\lambda=0$ one has
\begin{eqnarray}
\min_{\gamma\in \mathbb{R}}\left\{\sup_{X^*\in L^q_+}\{\langle X^*,X\rangle-\gamma\langle1_{\Omega},X^*\rangle\}+\gamma\right\}=\min_{\gamma\in \mathbb{R},~X\leq \gamma}\gamma=\operatorname{ess}\sup(X).\label{g_formula13}
\end{eqnarray}
Bringing \eqref{g_formula12} and \eqref{g_formula13} together implies that
\begin{eqnarray*}
g^*(X)=\min\left\{\min_{\lambda>0}\left\{\lambda\ln\left(\frac{\mathbb{E}\left(e^{\frac{X}{\lambda}}\right)}{\alpha}\right)\right\}, \operatorname{ess}\sup(X)\right\}=\min\{\operatorname{EV@R}_{1-\alpha}(X),\operatorname{ess}\sup(X)\}.
\end{eqnarray*}
As $\operatorname{EV@R}_{1-\alpha}(X)\leq\operatorname{ess}\sup(X)$ for any $X\in L^p$ (see \cite[Remark 2.7]{AJP}), we have that $g^*(X)=\operatorname{EV@R}_{1-\alpha}(X)$. Further, by the Fenchel-Moreau theorem it holds $g=g^{**}$, which yields that $g$ is the conjugate function of $\operatorname{EV@R}_{1-\alpha}$ and the formula of the conjugate function of $g^*$ given in \eqref{g_formula} is a dual representation of the entropic value at risk similar to the one in \cite[Theorem 4.9]{AJP} (other dual representations of the entropic value-at-risk were proposed in \cite{AJM, AAJ}).

From here, one can also deduce a formula for the subdifferential of the entropic value at risk at $X\in L^p$, namely
\begin{eqnarray*}
&\partial \operatorname{EV@R}_{1-\alpha}(X)=\left\{X^*\in L^q:\operatorname{EV@R}_{1-\alpha}(X)+g(X^*)=\langle X^*,X\rangle\right\}&\\
&=\left\{X^*\in L^q_+: \operatorname{EV@R}_{1-\alpha}(X)=\langle X^*,X\rangle,~\mathbb{E}(X^*\ln(X^*))\leq -\ln\alpha,~\mathbb{E}X^*=1\right\}.&
\end{eqnarray*}
Finally, let us mention that we can use the formula of the conjugate function of $\operatorname{EV@R}_{1-\alpha}$ to study the following generalized portfolio optimization problem
\begin{eqnarray*}
\inf_{\lambda_i\geq 0,~ i=1,\hdots,n,\atop\lambda=(\lambda_1, \hdots, \lambda_n)^\top\in D,~\sum\limits_{i=1}^n\lambda_i=1}\left\{\operatorname{EV@R}_{1-\alpha}(G(\lambda,R)\right\}
\end{eqnarray*}
via conjugate duality, where $G(\lambda,R)$ is a random variable and $R$ is an $m$-dimensional vector of risk factors with a known probability distribution, characterizing the portfolio return (see \cite{AJF}). A further application of the formula of the conjugate function of $\operatorname{EV@R}_{1-\alpha}$ arises thus in machine learning with uncertainty in the input data, as considered in \cite{AJM}.

\label{ThmEpi} Let $p>0$ and
\begin{eqnarray*}
h:\mathbb{R}\rightarrow \mathbb{R},~h(x)= \begin{cases}
 px\ln x, & \quad \text{if } x\geq 0,\\

  +\infty,  & \quad \text{if }  x<0.
\end{cases}
\end{eqnarray*}
Then it holds for all $(x,\xi)\in \mathbb{R}\times \mathbb{R}$ that
\begin{eqnarray*}
P_{\operatorname*{epi} h}(x,\xi)=\begin{cases}
 (x,\xi), & \quad \text{if } px\ln x\leq \xi,\\
 (0,\xi), & \quad \text{if } x\leq0\text{ and }\xi\geq 0,\\
 (e^{\bar z},p\bar ze^{\bar z}),  & \quad \text{otherwise,}
\end{cases}
\end{eqnarray*}
where $\bar z\in \mathbb{R}$ is the unique solution of the equation
\begin{eqnarray}\label{root}
(p^2z^2+p^2z+1)e^z-p\xi(z+1)-x=0
\end{eqnarray}
that fulfills $p\bar ze^{\bar z}\geq \xi$. More precisely, for $\xi\leq -p/e$ it holds $\bar z\in \mathbb{R}$, when $-p/e<\xi\leq 0$ and $x\leq 1/e$ one has $\bar z\in (-\infty,W_{-1}(\xi/p)]$, and when $-p/e<\xi\leq 0$ and $x> 1/e$ one has $\bar z\in [W(\xi/p),+\infty]$, while if $\xi>0$ it holds $\bar z\in [W(\xi/p),+\infty)$.

\label{co4} Let $0<p\leq 1$, then it holds for all $(x,\xi)\in \mathbb{R}\times \mathbb{R}$ that
\begin{eqnarray*}
P_{\operatorname*{epi} h}(x,\xi)=\begin{cases}
 (x,\xi), & \quad \text{if } px\ln x\leq \xi,\\
 (0,\xi), & \quad \text{if } x\leq0\text{ and }\xi\geq 0,\\
 (e^{\bar z},p\bar ze^{\bar z}),  & \quad \text{otherwise,}
\end{cases}
\end{eqnarray*}
where $\bar z\in \mathbb{R}$ is the unique solution of \eqref{root} that fulfills $p\bar ze^{\bar z}\geq \xi$. More precisely, exactly one of the following six cases holds\begin{enumerate}
  \item[(i)] $\xi\leq -\frac{p}{e}$ and $x<0$, then $\overline{z}\in \mathbb{R}$ is unique and $\overline{z}\in(-\infty,0]$;
  \item[(ii)] $\xi\leq -\frac{p}{e}$ and $x\geq 0$, then $\overline{z}\in \mathbb{R}$ is unique and $\overline{z}\in (-\infty,x]$;
    \item[(iii)] $-\frac{p}{e} <\xi \leq 0$ and $x<0$, then $\overline{z}\in \mathbb{R}$ is unique and $\bar z\in (-\infty,W_{-1}(\xi/p)]$;
  \item[(iv)] $-\frac{p}{e} <\xi \leq 0$ and $0\leq x\leq \frac{1}{e}$, then $\overline{z}\in \left[W_{-1}\left(\frac{\xi}{p}\right)+\ln(x)-1,W_{-1}\left(\frac{\xi}{p}\right)\right]$;
  \item[(v)] $-\frac{p}{e} <\xi \leq 0$ and $x> \frac{1}{e}$, then $\overline{z}\in\left[W\left(\frac{\xi}{p}\right),W\left(\frac{\xi}{p}\right)+\ln(x)+2\right]$;
  \item[(vi)] $\xi>0$, then $x>1$ and $\overline{z}\in \left[W\left(\frac{\xi}{p}\right),W\left(\frac{\xi}{p}\right)+\ln(x)+1\right]$.
\end{enumerate}

